analyze.mjs.text:
// Classifies a set of per-script probe results (real HTTP responses,
// collected by probe.mjs's live requests) into a verdict about whether a
// script's production source map is publicly readable, and whether that map
// embeds full original source text.
//
// Pure function, no I/O, no network -- imported identically by the CLI
// (check.mjs) and the browser page (index.html).
//
// What each classification means:
//
//   exposed    The script carries a sourceMappingURL comment and the map it
//              points at is publicly fetchable and parses as a source map.
//              Findings from this category carry two severities:
//                danger  the map also embeds `sourcesContent` -- the full
//                        original, unminified source text of every listed
//                        file, readable by anyone who requests the map.
//                notice  the map is fetchable but has no `sourcesContent`,
//                        so only the original file/folder paths (`sources`)
//                        are exposed -- internal structure, not the text.
//   blocked    The script references a map, but the map itself returned a
//              clean 401/403/404 -- the reference survived into production
//              but the file was not (or is no longer) actually served. This
//              is the common half-fixed state and is a healthy outcome.
//   clean      No sourceMappingURL comment at all -- the most common
//              correctly-configured production case.
//   error      The script itself failed to fetch, or the map fetch failed
//              without a clean HTTP status (network error, timeout, a
//              browser's CORS-blocked "failed to fetch", or a response that
//              was not valid JSON). Never read as either exposed or safe --
//              an error is not evidence of anything either way.

function classifyOne(result) {
  const scriptUrl = result?.scriptUrl ?? '(unknown script)';
  if (!result || (result.hasReference === false && result.error)) {
    return {
      scriptUrl, category: 'error', mapUrl: null, status: result?.status ?? null,
      sourcesCount: 0, hasSourcesContent: false, sampleSources: [],
      error: result?.error ?? 'request failed',
    };
  }

  if (!result.hasReference) {
    return {
      scriptUrl, category: 'clean', mapUrl: null, status: null,
      sourcesCount: 0, hasSourcesContent: false, sampleSources: [], error: null,
    };
  }

  if (result.mapFetchable) {
    return {
      scriptUrl, category: 'exposed', mapUrl: result.mapUrl, status: result.status,
      sourcesCount: result.sourcesCount ?? 0, hasSourcesContent: Boolean(result.hasSourcesContent),
      sampleSources: result.sampleSources ?? [], error: null,
    };
  }

  if (result.status === 401 || result.status === 403 || result.status === 404) {
    return {
      scriptUrl, category: 'blocked', mapUrl: result.mapUrl, status: result.status,
      sourcesCount: 0, hasSourcesContent: false, sampleSources: [], error: null,
    };
  }

  return {
    scriptUrl, category: 'error', mapUrl: result.mapUrl, status: result.status ?? null,
    sourcesCount: 0, hasSourcesContent: false, sampleSources: [],
    error: result.error ?? 'the referenced map could not be classified',
  };
}

/**
 * @param {string|null} pageUrl - the page checked, for display only
 * @param {object[]} scripts - probe.mjs's per-script results
 * @param {{pageError?: string|null, truncated?: boolean}} [meta]
 */
export function buildReport(pageUrl, scripts, meta = {}) {
  const list = Array.isArray(scripts) ? scripts : [];
  const classified = list.map(classifyOne);

  const exposed = classified.filter((c) => c.category === 'exposed');
  const findings = exposed.map((c) => ({
    id: c.hasSourcesContent ? 'source-map-full-source-exposed' : 'source-map-paths-exposed',
    severity: c.hasSourcesContent ? 'danger' : 'notice',
    scriptUrl: c.scriptUrl,
    title: c.hasSourcesContent
      ? `A source map for "${shortName(c.scriptUrl)}" exposes full original source text`
      : `A source map for "${shortName(c.scriptUrl)}" is publicly readable`,
    detail: c.hasSourcesContent
      ? `${c.sourcesCount} original source file(s) are readable in full at the map URL, ` +
        `including any comments, internal identifiers, or hardcoded values that were only ` +
        `stripped from the minified script -- not from the map.`
      : `${c.sourcesCount} original file/folder path(s) are readable at the map URL ` +
        `(no inlined source text, only the paths): ${c.sampleSources.slice(0, 3).join(', ')}` +
        `${c.sourcesCount > 3 ? ', …' : ''}.`,
    mapUrl: c.mapUrl,
    evidenceStatus: c.status != null ? `HTTP ${c.status}` : 'inline data: URI',
  }));

  const blocked = classified.filter((c) => c.category === 'blocked');
  const clean = classified.filter((c) => c.category === 'clean');
  const errors = classified.filter((c) => c.category === 'error');

  const pageError = meta.pageError ?? null;
  const dangerCount = findings.filter((f) => f.severity === 'danger').length;
  const noticeCount = findings.filter((f) => f.severity === 'notice').length;
  const incomplete = Boolean(pageError) || errors.length > 0;

  return {
    pageUrl,
    scriptsChecked: classified.length,
    truncated: Boolean(meta.truncated),
    pageError,
    classified,
    findings,
    blocked,
    clean,
    errors,
    dangerCount,
    noticeCount,
    ok: !pageError && dangerCount === 0 && noticeCount === 0,
    incomplete,
  };
}

function shortName(url) {
  try {
    const { pathname } = new URL(url);
    const parts = pathname.split('/').filter(Boolean);
    return parts.length > 0 ? parts[parts.length - 1] : url;
  } catch {
    return url;
  }
}

check.mjs.text:
#!/usr/bin/env node
// CLI: fetches a page's HTML (or an explicit list of script URLs you name),
// finds every script's own sourceMappingURL comment, and reports which
// scripts' production source maps are publicly readable -- and whether they
// embed full original source text (`sourcesContent`) or only file paths.
// Your machine, real requests -- no request goes through this portfolio.
//
//   node check.mjs <page-url> [--json] [--timeout <ms>]
//   node check.mjs --script <js-url> [--script <js-url> ...] [--json]
//
// Only run this against a site you own or are authorised to test -- treat it
// the same as you would `curl` aimed at someone else's server. This never
// sends anything but GET requests and never writes/modifies anything on the
// target.
//
// Exit code 0 when no script's source map was found to be publicly exposed;
// 1 when at least one is exposed, or the page/some scripts could not be
// checked at all.

import { checkPage } from './probe.mjs';
import { buildReport } from './analyze.mjs';

function formatText(report) {
  const lines = [];
  lines.push(`Page: ${report.pageUrl ?? '(explicit script list)'}`);
  lines.push(`Scripts checked: ${report.scriptsChecked}${report.truncated ? ' (list truncated at the cap)' : ''}`);
  lines.push('');

  if (report.pageError) {
    lines.push(`Could not read the page: ${report.pageError}`);
    lines.push('Check the URL, or pass explicit script URLs with --script instead.');
    return lines.join('\n');
  }

  if (report.findings.length === 0) {
    lines.push('No script\'s source map was found to be publicly readable.');
  } else {
    for (const f of report.findings) {
      lines.push(`!! [${f.severity.toUpperCase()}] ${f.title}`);
      lines.push(`     ${f.detail}`);
      lines.push(`     map: ${f.mapUrl}`);
      lines.push(`     evidence: ${f.evidenceStatus}`);
      lines.push('');
    }
  }

  if (report.blocked.length > 0) {
    lines.push('');
    lines.push(
      `${report.blocked.length} script(s) reference a map that is not actually served (401/403/404) -- ` +
        `a healthy outcome: ${report.blocked.map((c) => shortName(c.scriptUrl)).join(', ')}`,
    );
  }
  if (report.errors.length > 0) {
    lines.push('');
    lines.push(
      `${report.errors.length} script(s) could not be checked: ` +
        report.errors.map((c) => `${shortName(c.scriptUrl)} (${c.error})`).join('; '),
    );
  }

  lines.push('');
  lines.push(
    'This is evidence from the requests above, not a full security audit -- see README.md for ' +
      'what this tool does and does not check.',
  );
  return lines.join('\n');
}

function shortName(url) {
  try {
    const { pathname } = new URL(url);
    const parts = pathname.split('/').filter(Boolean);
    return parts.length > 0 ? parts[parts.length - 1] : url;
  } catch {
    return url;
  }
}

function parseArgs(argv) {
  const scriptUrls = [];
  let pageUrl = null;
  let json = false;
  let timeoutMs;
  for (let i = 0; i < argv.length; i++) {
    if (argv[i] === '--json') json = true;
    else if (argv[i] === '--timeout') timeoutMs = Number(argv[++i]);
    else if (argv[i] === '--script') scriptUrls.push(argv[++i]);
    else if (!argv[i].startsWith('--') && pageUrl === null) pageUrl = argv[i];
  }
  return { pageUrl, scriptUrls, json, timeoutMs };
}

/** Pure orchestration: given a checkPage function (real network, or a stub in
 * tests), fetch and classify. Kept separate from main() so tests can inject
 * a fake `checkPageFn` instead of hitting the network. */
export async function runCheck(pageUrl, { scriptUrls, checkPageFn = checkPage, timeoutMs } = {}) {
  const { scripts, pageError, truncated } = await checkPageFn(pageUrl, {
    scriptUrls: scriptUrls?.length ? scriptUrls : undefined,
    ...(timeoutMs ? { timeoutMs } : {}),
  });
  return buildReport(pageUrl, scripts, { pageError, truncated });
}

async function main() {
  const args = parseArgs(process.argv.slice(2));
  if (!args.pageUrl && args.scriptUrls.length === 0) {
    console.error('Usage: node check.mjs <page-url> [--json] [--timeout <ms>]');
    console.error('       node check.mjs --script <js-url> [--script <js-url> ...] [--json]');
    console.error('Only run this against a site you own or are authorised to test.');
    process.exit(2);
  }
  if (args.pageUrl) {
    try {
      // eslint-disable-next-line no-new
      new URL(args.pageUrl);
    } catch {
      console.error(`Not a valid URL: ${args.pageUrl}`);
      process.exit(2);
    }
  }

  const report = await runCheck(args.pageUrl, { scriptUrls: args.scriptUrls, timeoutMs: args.timeoutMs });

  if (args.json) {
    console.log(JSON.stringify(report, null, 2));
  } else {
    console.log(formatText(report));
  }
  process.exit(report.ok ? 0 : 1);
}

if (import.meta.url === `file://${process.argv[1]}`) {
  main();
}

probe.mjs.text:
// Real-network layer: fetches a page (or an explicit list of script URLs),
// finds each `<script src>`, reads the script's own trailing
// `//# sourceMappingURL=` comment, and -- when that map is not an inline
// `data:` URI -- fetches the referenced `.map` file to see whether it is
// publicly readable and whether it embeds full original source text.
//
// Deliberately the same module imported unmodified by the CLI (Node 22's
// built-in `fetch`) and by the browser page (`index.html` imports it
// directly), the same shape `ventures/supabase-rls-check/probe.mjs`
// documents. Whether a browser run can complete depends on the target's own
// CORS policy for a plain cross-origin GET -- a page's HTML document is
// often not served with permissive CORS, while static JS/CSS assets on many
// CDNs and static-site hosts commonly are (they already need it for
// cross-origin `<script type="module" crossorigin>` and Web Worker imports).
// When a fetch is blocked this way, the browser reports a generic network
// error with no HTTP status attached -- this module never guesses which
// cause it was, and reports it as an unclassified `error` either way; the
// CLI, run from a machine rather than a browser tab, is not subject to CORS
// at all and is the one path guaranteed to complete the check.
//
// This module only ever talks to the one page and the script/map URLs
// derived from it (or explicitly supplied by the caller). It sends nothing
// anywhere but GET requests to hosts the caller already named.

const DEFAULT_TIMEOUT_MS = 10_000;
const USER_AGENT =
  'source-map-leak-check/1 (+https://duncan-haywood.github.io/monorepo-projects/source-map-leak-check/)';
const MAX_BODY_BYTES = 5_000_000; // 5 MB cap per fetched file, script or map

function base64ToUtf8(b64) {
  const binary = atob(b64);
  const bytes = Uint8Array.from(binary, (c) => c.charCodeAt(0));
  return new TextDecoder('utf-8').decode(bytes);
}

async function timedFetch(url, init, timeoutMs, fetchImpl) {
  const doFetch = fetchImpl ?? globalThis.fetch;
  if (typeof doFetch !== 'function') {
    throw new Error('no fetch implementation available in this environment');
  }
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    return await doFetch(url, { ...init, signal: controller.signal });
  } finally {
    clearTimeout(timer);
  }
}

async function fetchText(url, { timeoutMs = DEFAULT_TIMEOUT_MS, fetchImpl } = {}) {
  let res;
  try {
    res = await timedFetch(
      url,
      { method: 'GET', headers: { 'user-agent': USER_AGENT, accept: '*/*' } },
      timeoutMs,
      fetchImpl,
    );
  } catch (err) {
    return { ok: false, status: null, text: null, error: err.message ?? String(err) };
  }
  if (!res.ok) {
    return { ok: false, status: res.status, text: null, error: `HTTP ${res.status}` };
  }
  let text;
  try {
    text = res.body?.getReader ? await readCapped(res, MAX_BODY_BYTES) : await res.text();
  } catch (err) {
    return { ok: false, status: res.status, text: null, error: err.message ?? String(err) };
  }
  return { ok: true, status: res.status, text, error: null };
}

// Caps how much of a response body this ever holds in memory -- a script or
// map file has no reason to run into the hundreds of megabytes for this
// check, and a truncated read is still enough to find (or fail to find) the
// sourceMappingURL comment near the end of a normally-sized bundle.
async function readCapped(res, maxBytes) {
  if (!res.body?.getReader) return res.text();
  const reader = res.body.getReader();
  const chunks = [];
  let total = 0;
  for (;;) {
    const { done, value } = await reader.read();
    if (done) break;
    total += value.byteLength;
    chunks.push(value);
    if (total >= maxBytes) {
      try { await reader.cancel(); } catch { /* best effort */ }
      break;
    }
  }
  const combined = new Uint8Array(total);
  let offset = 0;
  for (const chunk of chunks) {
    combined.set(chunk, offset);
    offset += chunk.byteLength;
  }
  return new TextDecoder('utf-8').decode(combined);
}

/** Finds every `<script src="...">` tag and resolves each src against
 * `baseUrl`. Ignores inline scripts (no `src`) -- out of scope, since an
 * inline script cannot carry an external source map reference worth
 * fetching separately. */
export function extractScriptSrcs(html, baseUrl) {
  const re = /<script\b[^>]*\bsrc\s*=\s*["']([^"']+)["'][^>]*>/gi;
  const seen = new Set();
  let m;
  while ((m = re.exec(html)) !== null) {
    try {
      seen.add(new URL(m[1], baseUrl).toString());
    } catch {
      // an unresolvable src (e.g. a template placeholder) is skipped, not fatal
    }
  }
  return [...seen];
}

/** Returns the last `//# sourceMappingURL=` (or legacy `//@`) comment's
 * value, or null. Per the source map spec a file may carry at most one
 * meaningful reference; if a bundler concatenated files that each carried
 * one, the last is the one a browser's own devtools would honour. */
export function extractSourceMappingUrl(jsText) {
  const re = /\/\/[#@]\s*sourceMappingURL=(\S+)/g;
  let last = null;
  let m;
  while ((m = re.exec(jsText)) !== null) last = m[1].trim();
  return last;
}

function decodeInlineSourceMap(dataUri) {
  const base64Match = /^data:[^,]*;base64,([\s\S]*)$/.exec(dataUri);
  if (base64Match) return JSON.parse(base64ToUtf8(base64Match[1]));
  const plainMatch = /^data:[^,]*,([\s\S]*)$/.exec(dataUri);
  if (plainMatch) return JSON.parse(decodeURIComponent(plainMatch[1]));
  throw new Error('unrecognised data: URI for an inline source map');
}

/** Full per-script check: fetch the script, look for a sourceMappingURL
 * comment, and if present, resolve and fetch (or inline-decode) the map to
 * see whether it is readable and whether it embeds full source text. */
export async function checkScript(scriptUrl, { timeoutMs, fetchImpl } = {}) {
  const scriptRes = await fetchText(scriptUrl, { timeoutMs, fetchImpl });
  if (!scriptRes.ok) {
    return {
      scriptUrl, hasReference: false, mapUrl: null, mapFetchable: false,
      sourcesCount: 0, hasSourcesContent: false, sampleSources: [],
      status: scriptRes.status, error: scriptRes.error,
    };
  }

  const mappingUrl = extractSourceMappingUrl(scriptRes.text);
  if (!mappingUrl) {
    return {
      scriptUrl, hasReference: false, mapUrl: null, mapFetchable: false,
      sourcesCount: 0, hasSourcesContent: false, sampleSources: [],
      status: null, error: null,
    };
  }

  let mapJson;
  let mapUrl;
  let mapStatus = null;
  let mapError = null;

  if (mappingUrl.startsWith('data:')) {
    mapUrl = '(inline data: URI in the script itself)';
    try {
      mapJson = decodeInlineSourceMap(mappingUrl);
    } catch (err) {
      return {
        scriptUrl, hasReference: true, mapUrl, mapFetchable: false,
        sourcesCount: 0, hasSourcesContent: false, sampleSources: [],
        status: null, error: `inline source map could not be decoded: ${err.message}`,
      };
    }
  } else {
    try {
      mapUrl = new URL(mappingUrl, scriptUrl).toString();
    } catch {
      return {
        scriptUrl, hasReference: true, mapUrl: null, mapFetchable: false,
        sourcesCount: 0, hasSourcesContent: false, sampleSources: [],
        status: null, error: `sourceMappingURL is not a resolvable URL: ${mappingUrl}`,
      };
    }
    const mapRes = await fetchText(mapUrl, { timeoutMs, fetchImpl });
    mapStatus = mapRes.status;
    if (!mapRes.ok) {
      return {
        scriptUrl, hasReference: true, mapUrl, mapFetchable: false,
        sourcesCount: 0, hasSourcesContent: false, sampleSources: [],
        status: mapStatus, error: mapRes.error,
      };
    }
    try {
      mapJson = JSON.parse(mapRes.text);
    } catch (err) {
      return {
        scriptUrl, hasReference: true, mapUrl, mapFetchable: false,
        sourcesCount: 0, hasSourcesContent: false, sampleSources: [],
        status: mapStatus, error: `map was fetched but is not valid JSON: ${err.message}`,
      };
    }
  }

  const sources = Array.isArray(mapJson?.sources) ? mapJson.sources : [];
  const sourcesContent = Array.isArray(mapJson?.sourcesContent) ? mapJson.sourcesContent : [];
  const hasSourcesContent = sourcesContent.some((s) => typeof s === 'string' && s.length > 0);

  return {
    scriptUrl, hasReference: true, mapUrl, mapFetchable: true,
    sourcesCount: sources.length, hasSourcesContent,
    sampleSources: sources.slice(0, 5),
    status: mapStatus, error: null,
  };
}

/** Full run: either check the explicit `scriptUrls` given, or fetch
 * `pageUrl`'s HTML and derive the list from its own `<script src>` tags. */
export async function checkPage(pageUrl, { scriptUrls: givenScripts, timeoutMs, fetchImpl, maxScripts = 40 } = {}) {
  let scriptUrls = givenScripts;
  if (!scriptUrls || scriptUrls.length === 0) {
    if (!pageUrl) throw new Error('either a page URL or an explicit list of script URLs is required');
    const pageRes = await fetchText(pageUrl, { timeoutMs, fetchImpl });
    if (!pageRes.ok) {
      return { pageUrl, scripts: [], pageError: pageRes.error, truncated: false };
    }
    scriptUrls = extractScriptSrcs(pageRes.text, pageUrl);
  }

  const capped = scriptUrls.slice(0, maxScripts);
  const scripts = await Promise.all(capped.map((u) => checkScript(u, { timeoutMs, fetchImpl })));
  return { pageUrl: pageUrl ?? null, scripts, pageError: null, truncated: scriptUrls.length > capped.length };
}

usage.mjs.text:
// Records an anonymous, aggregate-only local usage count: the event name and
// the current day, kept in the visitor's own browser. It never stores the
// page URL, any script URL, or anything about which files or source text
// came back -- that is exactly the kind of thing that must not be
// transmitted or retained anywhere, and this tool never reads it off the
// visitor's machine either.

const STORAGE_KEY = 'source-map-leak-check-usage';

function honorsBrowserSignal() {
  try {
    return globalThis.navigator?.doNotTrack === '1' || globalThis.navigator?.globalPrivacyControl === true;
  } catch {
    return false;
  }
}

export function recordUsage(storage = globalThis.localStorage, optedOut = false, event = 'check_run') {
  if (optedOut || !storage || readOptOut(storage) || honorsBrowserSignal()) return;
  try {
    const today = new Date().toISOString().slice(0, 10);
    const current = JSON.parse(storage.getItem(STORAGE_KEY) || '{}');
    current[event] = (current[event] || 0) + 1;
    current.last_day = today;
    storage.setItem(STORAGE_KEY, JSON.stringify(current));
  } catch {
    // A browser refusing site data must not stop the page computing a result.
  }
}

// The opt-out choice is kept in its own key, not in the counters: opting out
// *removes* the counters, so a flag stored inside them would be deleted by
// the very act it records.
export function readOptOut(storage = globalThis.localStorage) {
  try {
    return storage?.getItem(`${STORAGE_KEY}-opt-out`) === '1';
  } catch {
    return false;
  }
}

export function writeOptOut(storage = globalThis.localStorage, optedOut = false) {
  if (!storage) return;
  if (optedOut) {
    try { storage.removeItem(STORAGE_KEY); } catch { /* storage is optional */ }
    try { storage.setItem(`${STORAGE_KEY}-opt-out`, '1'); } catch { /* storage is optional */ }
  } else {
    try { storage.removeItem(`${STORAGE_KEY}-opt-out`); } catch { /* storage is optional */ }
  }
}
